/*
 * A076974  Increasing sequence where each number is unequal to 2 mod all
 *          previous numbers.
 * https://oeis.org/A076974
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 23, u16 n <= 3207, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence generated by a modified sieve: each term is the smallest integer
   > previous term not congruent to 2 modulo any earlier term. */
#include <stdlib.h>

typedef struct { seq_t val; idx_t idx; } preg;

static void heap_init(void);
static void heap_push(seq_t val, idx_t idx);
static void heap_pop(void);
static preg heap_top(void);
static void heap_sift_up(size_t i);
static void heap_sift_down(size_t i);
static void grow_seq(size_t needed);
static void grow_heap(size_t needed);

static seq_t *seq = NULL;
static size_t seq_cap = 0;
static idx_t seq_len = 0;

static preg *heap = NULL;
static size_t heap_size = 0;
static size_t heap_cap = 0;

/* Initialize the heap once. */
static void heap_init(void)
{
    if (!heap) {
        heap_cap = 64;
        heap = (preg*)malloc(heap_cap * sizeof(preg));
    }
}

/* Ensure sequence buffer can hold 'needed' elements. */
static void grow_seq(size_t needed)
{
    if (needed <= seq_cap) return;
    size_t new_cap = seq_cap ? seq_cap * 2 : 64;
    while (new_cap < needed) new_cap <<= 1;
    seq = (seq_t*)realloc(seq, new_cap * sizeof(seq_t));
    seq_cap = new_cap;
}

/* Ensure heap buffer can hold 'needed' elements. */
static void grow_heap(size_t needed)
{
    if (needed <= heap_cap) return;
    size_t new_cap = heap_cap ? heap_cap * 2 : 64;
    while (new_cap < needed) new_cap <<= 1;
    heap = (preg*)realloc(heap, new_cap * sizeof(preg));
    heap_cap = new_cap;
}

/* Push a new node onto the min‑heap. */
static void heap_push(seq_t val, idx_t idx)
{
    grow_heap(heap_size + 1);
    heap[heap_size].val = val;
    heap[heap_size].idx = idx;
    heap_sift_up(heap_size);
    heap_size++;
}

/* Remove the top element of the heap. */
static void heap_pop(void)
{
    if (heap_size == 0) return;
    heap[0] = heap[--heap_size];
    heap_sift_down(0);
}

/* Return the top element without removing it. */
static preg heap_top(void)
{
    preg p; p.val = 0; p.idx = (idx_t)(-1);
    if (heap_size) p = heap[0];
    return p;
}

/* Sift the element at position i up to restore heap property. */
static void heap_sift_up(size_t i)
{
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent].val <= heap[i].val) break;
        preg tmp = heap[i];
        heap[i] = heap[parent];
        heap[parent] = tmp;
        i = parent;
    }
}

/* Sift the element at position i down to restore heap property. */
static void heap_sift_down(size_t i)
{
    size_t n = heap_size;
    while (1) {
        size_t left  = (i << 1) + 1;
        size_t right = left + 1;
        size_t smallest = i;
        if (left < n && heap[left].val < heap[smallest].val) smallest = left;
        if (right < n && heap[right].val < heap[smallest].val) smallest = right;
        if (smallest == i) break;
        preg tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
}

/* Return the a(n) term of the sequence (1‑based index). */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0; /* undefined for n<1 */

    /* Lazy initialization of the heap. */
    heap_init();

    while (seq_len < n) {
        /* First term. */
        if (seq_len == 0) {
            grow_seq(1);
            seq[0] = (seq_t)2;
            seq_len = 1;
            heap_push((seq_t)2, (idx_t)0);
            continue;
        }

        seq_t cand = seq[seq_len - 1] + (seq_t)1;
        while (1) {
            /* Advance heap nodes that are below the candidate. */
            while (heap_size > 0 && heap[0].val < cand) {
                preg cur = heap[0];
                heap_pop();
                heap_push(cur.val + seq[cur.idx], cur.idx);
            }

            if (heap_size > 0 && heap[0].val == cand) {
                /* Candidate eliminated; try the next integer. */
                cand++;
                continue;
            }

            /* Found the next term. */
            grow_seq(seq_len + 1);
            seq[seq_len++] = cand;
            heap_push((seq_t)2, (idx_t)(seq_len - 1));
            break;
        }
    }
    return seq[n - 1];
}
